  'Ware grootte': 'Действителен размер',
  'Pagina-einden gelden alleen op paginabreedte.':
      'Разделянето на страници важи само при ширина на страницата.',
  'Hoe breed de leeskolom in de visuele modus is. Smal leest rustig, breed gebruikt meer van het scherm. Of je op die kolom, op paginabreedte of op het hele venster schrijft, kies je in de werkbalk.':
      'Колко широка е колоната за четене във визуалния режим. Тясната се чете спокойно, широката използва повече от екрана. Дали пишете в тази колона, в ширина на страницата или в целия прозорец, избирате от лентата с инструменти.',
  'De sprong "{doel}" wijst naar een dia die niet meer bestaat; tijdens het presenteren gebeurt er niets. Kies een andere doeldia.':
      'Скокът „{doel}“ сочи към слайд, който вече не съществува; по време на презентацията не се случва нищо. Изберете друг целеви слайд.',
  'In een cirkel': 'Кръг',
  'Onder elkaar': 'Списък',
  'Categorie': 'Категория',
  'Categorie toevoegen': 'Добавяне на категория',
  'Categorie opheffen (blokken blijven behouden)':
      'Премахване на категорията (блоковете се запазват)',
  'Uitleg': 'Описание',
  'Een keuzemenu: elk blok springt bij aanklikken naar een andere dia. Typ per blok een label en een uitleg, kies de doeldia en eventueel een afbeelding. Kies de indeling: raster, onder elkaar of in een cirkel. Met categorieën wissel je tijdens het presenteren tussen groepen blokken. Een blok zonder doel is gewone tekst.':
      'Меню за избор: всеки блок при щракване преминава към друг слайд. Въведете етикет и описание за всеки блок, изберете целевия слайд и по желание изображение. Изберете оформлението: мрежа, списък или кръг. С категориите превключвате между групи блокове по време на презентацията. Блок без цел е обикновен текст.',
  'Alleen een lege dia.': 'Само празен слайд.',
  'Hoofdstukken op nieuwe pagina': 'Глави на нова страница',
  'Elk hoofdstuk begint nu op een nieuwe pagina':
      'Сега всяка глава започва на нова страница',
  'Elk hoofdstuk begon al op een nieuwe pagina':
      'Всяка глава вече започваше на нова страница',
  'Snijtekens': 'Знаци за рязане',
  'Alleen in de LaTeX/PDF-export, en alleen met afloop. Vereist het crop-pakket in je TeX-installatie; een browser-afdruk van de HTML-export zet ze niet.':
      'Само в експорта LaTeX/PDF и само с разлив. Изисква пакета crop във вашата инсталация на TeX; отпечатването на HTML експорта от браузър не ги добавя.',
  'Deze paginaopmaak staat in dit document':
