  'https://app.voorbeeld/login': 'https://app.example/login',
  'Deze afbeelding naar het AI-model sturen?':
      'Да се изпрати ли това изображение до AI модела?',
  'De afbeelding gaat ongewijzigd naar':
      'Изображението ще бъде изпратено без промени до',
  'OciDeck lakt niets weg in een afbeelding: gezichten, tekst op een schermafdruk en gegevens in beeld gaan mee.':
      'OciDeck не заличава нищо в изображението: лица, текст на екранна снимка и видими данни се изпращат заедно с него.',
  'De beeldcontrole vond hier een of meer herkenbare gezichten.':
      'Проверката на изображенията откри тук едно или повече разпознаваеми лица.',
  'Naast de export komen twee bestanden te staan waarmee een ontvanger de redacties kan natrekken.':
      'До експорта се създават два файла, с които получателят може да провери заличаванията.',
  'somt op wat er is weggelaten, zonder de waarden zelf. Dit bestand mag met het rapport mee.':
      'изброява какво е пропуснато, без самите стойности. Този файл може да придружи доклада.',
  'bevat de sleutels waarmee elke weggelakte waarde is terug te rekenen. Stuur dit bestand niet mee: dan is de redactie ongedaan gemaakt. Bewaar het bij de bron.':
      'съдържа ключовете, с които всяка заличена стойност може да бъде възстановена. Не изпращайте този файл: така заличаването се обезсилва. Съхранявайте го при източника.',
  'slides': 'слайда',
  'Achtergehouden': 'Задържан',
  'Achtergehouden: strenger geclassificeerd dan de presentatie':
      'Задържан: класифициран по-строго от презентацията',
  '1 slide achtergehouden door haar TLP': '1 слайд задържан заради своя TLP',
  'slides achtergehouden door hun TLP': 'слайда задържани заради своя TLP',
  'Deze slides gaan niet mee bij presenteren, exporteren of in het pakket. Verhoog het TLP-niveau van de presentatie bij Presentatie-info om ze mee te nemen.':
      'Тези слайдове не се включват при представяне, експортиране или в пакета. Повишете нивото TLP на презентацията в Информация за презентацията, за да ги включите.',
  'Alle slides zijn achtergehouden door hun TLP-classificatie — niets om te tonen.':
      'Всички слайдове са задържани заради своята TLP класификация — няма какво да се покаже.',
  'Alle slides zijn achtergehouden door hun TLP-classificatie — niets om te exporteren.':
      'Всички слайдове са задържани заради своята TLP класификация — няма какво да се експортира.',
  'Alle slides zijn overgeslagen of achtergehouden door hun TLP-classificatie — niets om te tonen.':
      'Всички слайдове са пропуснати или задържани заради своята TLP класификация — няма какво да се покаже.',
  'Alle slides zijn overgeslagen of achtergehouden door hun TLP-classificatie — niets om te exporteren.':
      'Всички слайдове са пропуснати или задържани заради своята TLP класификация — няма какво да се експортира.',
  'Grafiekcijfers zijn niet opgeslagen — ze staan alleen nog in dit venster:':
      'Числата на диаграмите не бяха запазени — те съществуват само в този прозорец:',
  'In de browser is er geen crashherstel: sluit je dit tabblad, dan is niet-opgeslagen werk weg. Sla je presentatie zelf op.':
      'В браузъра няма възстановяване след срив: затворите ли този раздел, незапазената работа изчезва. Запазете презентацията си сами.',
  '•  De lokale CVE-database (je start de download zelf): OciDeck haalt de bulkgegevens op via api.github.com en het releasebestand waar dat adres naar wijst.':
      '•  Локалната база данни CVE (изтеглянето стартирате вие): OciDeck взема масовите данни през api.github.com и файла на изданието, към който сочи този адрес.',
  '•  CVE opzoeken (staat standaard uit): staat het aan, dan gaat je zoekterm naar de ingestelde CVE-spiegel en, als die niets vindt, naar de Europese database van ENISA en naar MITRE.':
      '•  Търсене на CVE (по подразбиране изключено): когато е включено, търсената от вас дума отива към зададеното CVE огледало, а ако то не открие нищо — към европейската база данни на ENISA и към MITRE.',
  '•  Een ingesloten YouTube- of Vimeo-video laadt de speler bij die dienst.':
      '•  Вградено видео от YouTube или Vimeo зарежда плейъра от съответната услуга.',
  '•  In de browser: weigert de browser een adres rechtstreeks op te halen, dan probeert OciDeck het via de server waar de app vandaan komt; dat adres komt dan bij die server terecht.':
      '•  В браузъра: ако браузърът откаже да извлече адрес директно, OciDeck опитва отново през сървъра, от който идва приложението; тогава този адрес стига до онзи сървър.',
  'Intrekken is niet vastgelegd. Bij de volgende start geldt uw toestemming weer.':
      'Оттеглянето не беше запазено. При следващото стартиране съгласието ви ще важи отново.',
  'Een tussenkop die een nieuw deel van de presentatie aankondigt. Houd het kort. Voeg via de afbeeldingsbibliotheek een achtergrondbeeld toe.':
      'Заглавие на раздел, което обявява нова част от презентацията. Дръжте го кратко. Добавете фоново изображение от библиотеката с изображения.',
  'Bronnen doorzoeken…': 'Търсене в източниците…',
  'Niet doorzocht': 'Не е претърсено',
  'Deze controle draait niet in de webversie: gezichtsherkenning vergt een systeembibliotheek die de browser niet heeft. Gebruik de desktopversie om afbeeldingen op gezichten na te kijken.':
      'Тази проверка не се изпълнява в уеб версията: разпознаването на лица изисква системна библиотека, която браузърът няма. Използвайте настолната версия, за да проверите изображенията за лица.',
  'Het token heeft lees- en schrijfrechten op de repository nodig. Gitea en Forgejo kennen geen server-side zoeken; OciDeck zoekt lokaal.':
      'Токенът се нуждае от права за четене и запис в хранилището. Gitea и Forgejo нямат търсене на сървъра; OciDeck търси локално.',
  'Het token heeft de repo-scope nodig (of fijnmazig: Contents lezen en schrijven).':
      'Токенът се нуждае от обхвата repo (или подробно: Contents за четене и запис).',
  'Het token heeft read_repository, write_repository en read_api nodig. Server-side zoeken vereist Advanced- of Exact Search.':
      'Токенът се нуждае от read_repository, write_repository и read_api. Търсенето на сървъра изисква Advanced или Exact Search.',
  'Snelle server-zoekopdracht — door indexeringsvertraging kan een net gewijzigd deck ontbreken.':
      'Бързо търсене на сървъра — поради забавяне на индексирането наскоро променена колода може да липсва.',
  'Media blijft niet bewaard in een los .md-bestand':
      'Медията не се запазва в обикновен .md файл',
  'Afbeeldingen, video en audio die je in dit tabblad koos, leven alleen in het geheugen. Een los .md-bestand bewaart ze niet — bij heropenen zijn ze weg. Exporteer als .ocideck-pakket om het beeld mee te nemen.':
      'Изображенията, видеото и звукът, които избрахте в този раздел, съществуват само в паметта. Обикновен .md файл не ги запазва — изчезват при повторно отваряне. Експортирайте като пакет .ocideck, за да вземете медията със себе си.',
  'Media verwijderd om privacyredenen':
      'Медията е премахната по съображения за поверителност',
  'Afbeeldingen door AI laten taggen?': 'Да маркира ли ИИ тези изображения?',
