  'Lager is beter': 'По-ниско е по-добре',
  'Hoger is beter': 'По-високо е по-добре',
  'Neutraal': 'Неутрално',
  'Nu': 'Сега',
  'Vorige rapportage': 'Предишен отчет',
  'Een scorecard toont hoogstens vijf cijfers; meer leest niet meer als een oordeel.':
      'Картата с показатели показва най-много пет числа; повече вече не се чете като оценка.',
  'Laat de vorige rapportage leeg als er nog geen meting was; de slide toont dan geen verandering.':
      'Оставете предишния отчет празен, ако още не е имало измерване; слайдът тогава не показва промяна.',
  'Bepaalt of een stijging groen of rood kleurt. De pijl volgt altijd de cijfers.':
      'Определя дали покачването е зелено или червено. Стрелката винаги следва числата.',
  'Een paar kerncijfers met het cijfer van de vorige rapportage ernaast, zodat de verandering het verhaal vertelt. Geef per cijfer aan of stijgen goed of slecht nieuws is.':
      'Няколко ключови числа с числото от предишния отчет до тях, така че историята да я разказва промяната. За всяко посочете дали покачването е добра или лоша новина.',
  'Zekere vondsten als fout behandelen':
      'Третиране на сигурните находки като грешки',
  'Normaal is een zekere vondst — een BSN, een IBAN, een e-mailadres — een waarschuwing die je kunt negeren. Aan maakt er een fout van, en dan kan de export erop blokkeren als je die instelling ook aan hebt staan. Bedoeld voor omgevingen waar zulke gegevens er echt niet doorheen mogen. Onzekere vondsten blijven een waarschuwing.':
      'Обикновено сигурна находка — ЕГН, IBAN, имейл адрес — е предупреждение, което можете да пренебрегнете. Включено я превръща в грешка и тогава износът може да блокира заради нея, ако и онази настройка е включена. Предназначено за среди, в които такива данни наистина не бива да преминават. Несигурните находки остават предупреждение.',
  'Medicare-nummer — een zorggegeven': 'номер Medicare — здравни данни',
  'bedrijfsnummer': 'номер на дружество',
  'zorgverzekeringsnummer (RAMQ) — een zorggegeven':
      'номер на здравна осигуровка (RAMQ) — здравни данни',
  'zorgverzekeringsnummer (OHIP) — een zorggegeven':
      'номер на здравна осигуровка (OHIP) — здравни данни',
  'bedrijfsnummer (BN)': 'номер на предприятие (BN)',
  'zorgverlenersnummer (NPI)': 'номер на здравен доставчик (NPI)',
  'Medicare-nummer (MBI) — een zorggegeven':
      'номер Medicare (MBI) — здравно данно',
  'wacht op verbinding': 'чака връзка',
  'Opgeslagen op deze computer, nog niet in de repository. Gaat mee zodra er weer verbinding is — of nu, met "Wachtrij legen".':
      'Запазено на този компютър, още не в хранилището. Ще замине веднага щом има връзка — или сега, с „Изпразване на опашката“.',
  'Branch (optioneel)': 'Клон (по избор)',
  'let op: de standaardbranch is': 'внимание: клонът по подразбиране е',
  'jij werkt op': 'вие работите на',
  'werkgeversnummer (EIN)': 'номер на работодател (EIN)',
  'laatste vier cijfers van een SSN': 'последните четири цифри на SSN',
  'geboortedatum, postcode en geslacht samen — die drie wijzen meestal één persoon aan, ook zonder naam':
      'дата на раждане, пощенски код и пол заедно — тези три обикновено сочат един човек, дори без име',
  'Het certificaat van deze server wordt niet vertrouwd. Bij een zelf gehoste server kun je het bekijken en vertrouwen bij Instellingen → Opslag.':
      'Сертификатът на този сървър не е доверен. При собствен сървър можете да го прегледате и да му се доверите в Настройки → Хранилище.',
  'Het certificaat van de forge wordt niet vertrouwd. Bij een zelf gehoste forge kun je het bekijken en vertrouwen bij Instellingen → Opslag.':
      'Сертификатът на този forge не е доверен. При собствен forge можете да го прегледате и да му се доверите в Настройки → Хранилище.',
  'Het certificaat van het endpoint wordt niet vertrouwd. Bij een zelf gehost endpoint kun je het bekijken en vertrouwen bij Instellingen → Opslag.':
      'Сертификатът на този endpoint не е доверен. При собствен endpoint можете да го прегледате и да му се доверите в Настройки → Хранилище.',
  'Het certificaat van de forge wordt niet vertrouwd — zelfondertekend, verlopen, of op een andere naam gesteld.':
      'Сертификатът на forge не е доверен — самоподписан, изтекъл или издаден на друго име.',
  'Het certificaat van het endpoint wordt niet vertrouwd — zelfondertekend, verlopen, of op een andere naam gesteld.':
      'Сертификатът на endpoint не е доверен — самоподписан, изтекъл или издаден на друго име.',
  'creditcardnummer': 'номер на кредитна карта',
  'beveiligingscode van een creditcard': 'код за сигурност на картата (CVV)',
  'gegevens in de sprekersnotities — onzichtbaar op de slide, wél in de export':
      'данни в бележките на докладчика — невидими на слайда, но влизат в експорта',
  'Certificaat vertrouwen?': 'Доверяване на този сертификат?',
  'Het certificaat van deze server is niet ondertekend door een erkende uitgever. Dat is gewoon bij een zelf gehoste server, maar het is ook hoe een afgeluisterde verbinding eruitziet.':
      'Сертификатът на този сървър не е подписан от признат издател. Това е нормално за собствен сървър, но така изглежда и прихваната връзка.',
  'Vergelijk de vingerafdruk hieronder met wat je server zelf toont. Komen ze overeen, dan praat je met de juiste machine.':
      'Сравнете отпечатъка по-долу с този, който показва самият ви сървър. Ако съвпадат, говорите с правилната машина.',
  'Uitgegeven aan': 'Издаден на',
  'Uitgegeven door': 'Издаден от',
  'Geldig tot': 'Валиден до',
  'Vingerafdruk (SHA-256)': 'Отпечатък (SHA-256)',
  'Alleen dit ene certificaat wordt vertrouwd. Vervangt de server het later, dan vraagt OciDeck het opnieuw.':
      'Доверява се само на този сертификат. Ако сървърът го смени по-късно, OciDeck ще попита отново.',
  'Vertrouwen': 'Доверяване',
  'Certificaat bekijken': 'Преглед на сертификата',
  'De plekken waar je presentaties bewaart en doorzoekt — mappen op deze computer, WebDAV-servers, S3-buckets en git-repositories door elkaar. Sleep ze in de volgorde die jij wilt: de bovenste van een soort geldt als standaard.':
      'Местата, където пазиш и търсиш презентациите си — папки на този компютър, WebDAV сървъри, S3 кофи и git хранилища разбъркани. Плъзни ги в реда, който искаш: най-горното от даден вид важи като подразбиращо се.',
  '•  S3-opslag: verbind je met een bucket, dan worden het endpoint, de bucketnaam en je toegangssleutel bewaard (de geheime sleutel veilig in de sleutelbos van je systeem) en worden de presentaties die je opent of opslaat naar die opslagdienst verstuurd.':
      '•  Хранилище S3: когато се свържеш с кофа, се запазват крайната точка, името на кофата и твоят ключ за достъп (тайният ключ сигурно в ключодържателя на системата ти), а презентациите, които отваряш или запазваш, се изпращат към тази услуга за съхранение.',
  '•  Git-opslag: verbind je met een repository, dan wordt je toegangstoken bewaard (veilig in de sleutelbos van je systeem) en worden de presentaties die je opslaat als commits naar die server verstuurd. Een werkkopie van de repository blijft onversleuteld op dit apparaat staan.':
      '•  Хранилище Git: когато се свържеш с хранилище, се запазва твоят токен за достъп (сигурно в ключодържателя на системата ти), а презентациите, които запазваш, се изпращат към този сървър като комити. Работно копие на хранилището остава нешифровано на това устройство.',
  'Voor de taal van dit deck ontbreken de ziekte- en aandoeningsnamen. Religie, politieke overtuiging en vakbondstermen worden wel herkend, en controlegetallen (BSN, IBAN, paspoort) werken altijd — maar reken er niet op dat een diagnose gevonden wordt.':
      'За езика на тази презентация липсват имената на заболявания. Религия, политически убеждения и синдикални термини се разпознават, а шаблоните с контролна цифра (ЕГН, IBAN, паспорт) работят винаги — но не разчитайте да бъде открита диагноза.',
  'niet getest': 'не е тествано',
  'Werkte op': 'Работеше на',
  'Je bent aangemeld, maar hebt hier geen toegang. Je wachtwoord is niet het probleem — vraag de beheerder om rechten op deze map.':
      'Влезли сте, но нямате достъп тук. Паролата не е проблемът — поискайте от администратора права за тази папка.',
  'Je token is geldig, maar mag dit niet. Geef het meer rechten, of wacht als de forge een limiet oplegt.':
      'Токенът ви е валиден, но няма права за това. Дайте му повече права или изчакайте, ако форджът налага ограничение.',
  'Het token is geldig, maar mag dit niet — geef het meer rechten op de repository.':
      'Токенът е валиден, но няма права за това — дайте му повече права върху хранилището.',
  'Aangemeld, maar geen toegang — je wachtwoord is niet het probleem. Vraag rechten op deze map.':
      'Влезли сте, но без достъп — паролата не е проблемът. Поискайте права за тази папка.',
  'Dit lijkt een volledige DAV-URL. Bij Nextcloud leidt OciDeck dat pad zelf af — hier hoort alleen de server te staan.':
      'Това прилича на пълен DAV адрес. При Nextcloud OciDeck сам извежда този път — тук принадлежи само сървърът.',
  'Overnemen': 'Приложи',
  'WebDAV is niet (goed) ingesteld — controleer de servergegevens bij Instellingen → Opslag.':
      'WebDAV не е настроен правилно — проверете данните за сървъра в Настройки → Хранилище.',
  'De git-repository is niet (goed) ingesteld — controleer server, eigenaar en repository bij Instellingen → Opslag.':
      'Git хранилището не е настроено правилно — проверете сървър, собственик и хранилище в Настройки → Хранилище.',
  'De servernaam van de forge bestaat niet, of is niet op te zoeken. Controleer de server-URL op een typefout.':
      'Името на сървъра на форджа не съществува или не може да бъде намерено. Проверете URL адреса на сървъра за печатна грешка.',
  'Deze forge heeft een privé- of LAN-adres. Markeer hem als vertrouwd intern bij Instellingen → Opslag.':
      'Този фордж има частен или LAN адрес. Отбележете го като доверен вътрешен в Настройки → Хранилище.',
  'De forge is niet bereikbaar — controleer je verbinding en de server-URL.':
      'Форджът е недостъпен — проверете връзката и URL адреса на сървъра.',
  'Aanmelden bij de forge mislukt. Controleer je token: het heeft leesrechten op de repository nodig, en schrijfrechten om op te slaan.':
      'Влизането във форджа е неуспешно. Проверете токена: нужни са му права за четене на хранилището и за писане, за да записва.',
  'Niet gevonden in de repository — of je token mag het niet zien.':
      'Не е намерено в хранилището — или токенът ви няма право да го вижда.',
  'De forge gaf een fout. Probeer het later opnieuw.':
      'Форджът върна грешка. Опитайте отново по-късно.',
  'Dit adres antwoordt niet als een forge. Klopt de soort forge bij Instellingen → Opslag?':
      'Този адрес не отговаря като фордж. Правилен ли е видът фордж в Настройки → Хранилище?',
  'Stel eerst een WebDAV-server in bij Instellingen → Opslag.':
      'Първо настройте WebDAV сървър в Настройки → Хранилище.',
  'Nodig wanneer de forge op een privé- of thuisnetwerk draait. Zonder deze vlag weigert de beveiliging een privé-adres.':
      'Нужно е, когато форджът работи в частна или домашна мрежа. Без този флаг проверката за сигурност отхвърля частен адрес.',
  'Vul server-URL, eigenaar en repository in':
      'Попълнете URL на сървъра, собственик и хранилище',
  'de standaardbranch heet': 'клонът по подразбиране се казва',
  'die wordt voortaan gebruikt': 'оттук нататък ще се използва той',
  'de repository is nog leeg; de eerste opslag vult hem':
      'хранилището все още е празно; първото запазване ще го запълни',
  'let op: dit token mag alleen lezen, dus opslaan zal mislukken':
      'внимание: този токен може само да чете, така че запазването ще се провали',
  'Aanmelden mislukt — controleer het token. Het heeft leesrechten op de repository nodig, en schrijfrechten om te kunnen opslaan.':
      'Влизането е неуспешно — проверете токена. Нужни са му права за четене на хранилището и за писане, за да може да записва.',
  'Repository niet gevonden — of je token mag hem niet zien. Controleer eigenaar en repositorynaam.':
      'Хранилището не е намерено — или токенът ви няма право да го вижда. Проверете собственика и името на хранилището.',
  'Dit adres antwoordt niet als een forge. Klopt de soort forge die je hebt gekozen?':
      'Този адрес не отговаря като фордж. Правилен ли е избраният вид фордж?',
  'kenteken': 'регистрационен номер',
  'Voor de taal van dit deck is er geen trefwoordenlijst voor bijzondere persoonsgegevens. Patronen met een controlegetal (BSN, IBAN, paspoort) werken wel; woorden als "diagnose" of "verdachte" worden niet herkend.':
      'За езика на тази презентация няма списък с ключови думи за специални категории лични данни. Шаблоните с контролна цифра (ЕГН, IBAN, паспорт) работят; думи като „диагноза“ или „заподозрян“ не се разпознават.',
  'Landpakketten voor identificatienummers':
      'Пакети по държави за идентификационни номера',
  'Nummers als het BSN of het PESEL zijn landgebonden. Heel Europa staat aan omdat de meeste van die nummers een controlegetal hebben: die aanzetten kost vrijwel geen valse meldingen. IBAN, e-mail, geheimen en paspoortstroken staan hier los van en worden altijd nagekeken.':
      'Номера като нидерландския BSN или полския PESEL са специфични за държава. Цяла Европа е включена, защото повечето от тези номера имат контролна цифра: включването им почти не струва фалшиви сигнали. IBAN, имейл, тайни и паспортни ленти са независими от това и винаги се проверяват.',
  'strafrechtelijk gegeven (verdachte)': 'наказателноправни данни (заподозрян)',
  'strafrechtelijk gegeven (aangever of slachtoffer)':
      'наказателноправни данни (жалбоподател или жертва)',
  'strafrechtelijk gegeven (getuige)': 'наказателноправни данни (свидетел)',
  'diagnosecode (ICD-10)': 'код на диагноза (МКБ-10)',
  'geneesmiddelcode (ATC)': 'код на лекарство (ATC)',
  'geboortedatum': 'дата на раждане',
  'locatiecoördinaten': 'координати на местоположение',
  'MAC-adres van een apparaat': 'MAC адрес на устройство',
  'IMEI van een toestel': 'IMEI на телефон',
  'ICCID van een simkaart': 'ICCID на SIM карта',
  'IMSI van een abonnee': 'IMSI на абонат',
  'sociale-mediaprofiel': 'профил в социална мрежа',
  'advertentie- of apparaat-ID': 'рекламен идентификатор или ID на устройство',
  'IP-adres': 'IP адрес',
  'machineleesbare zone van een paspoort of ID':
      'машинночетима зона на паспорт или лична карта',
  'De endpoint-naam bestaat niet, of is niet op te zoeken. Controleer het endpoint op een typefout.':
      'Името на крайната точка не съществува или не може да бъде намерено. Проверете я за печатна грешка.',
  'De endpoint-naam bestaat niet. Controleer het endpoint op een typefout.':
      'Името на крайната точка не съществува. Проверете я за печатна грешка.',
  'De servernaam bestaat niet, of is niet op te zoeken. Controleer de server-URL op een typefout.':
      'Името на сървъра не съществува или не може да бъде намерено. Проверете URL адреса на сървъра за печатна грешка.',
  'Deze server heeft een privé- of LAN-adres. Markeer hem als vertrouwd intern bij Instellingen → Opslag.':
      'Този сървър има частен или LAN адрес. Отбележете го като доверен вътрешен в Настройки → Хранилище.',
  'De server stuurt door naar een ander adres. Vul dat adres rechtstreeks in — een omleiding volgen we niet, want die kan de veiligheidscontrole omzeilen.':
      'Сървърът пренасочва към друг адрес. Въведете този адрес директно — не следваме пренасочвания, защото могат да заобиколят проверката за сигурност.',
  'De servernaam bestaat niet. Controleer de server-URL op een typefout.':
