  'Geen verbinding met de videobron': 'Няма връзка с източника на видеото',
  'Controleer de internetverbinding en probeer opnieuw.':
      'Проверете връзката с интернет и опитайте отново.',
  'Privacy blokkeert export': 'Поверителността блокира експорта',
  'privacybevinding(en) zonder keuze':
      'констатация(и) за поверителност без избор',
  'Persoonsgegevens, bijzondere gegevens en geheimen in de tekst':
      'Лични данни, специални данни и тайни в текста',
  'Slides, notities, tabellen, code, bestandspaden en URL\'s worden op dit apparaat doorzocht op identificerende nummers, financiële gegevens, contactgegevens, digitale identificatoren, geheimen, bijzondere persoonsgegevens (AVG art. 9/10), massagegevens en metadatalekken.':
      'Слайдовете, бележките, таблиците, кодът, пътищата до файлове и URL адресите се претърсват на това устройство за идентификационни номера, финансови данни, данни за контакт, цифрови идентификатори, тайни, специални категории лични данни (GDPR чл. 9/10), масови данни и изтичане на метаданни.',
  'Alleen een zekere treffer waarschuwt; waarschijnlijk en mogelijk blijven informatief. Een uitgezette regel vuurt nergens.':
      'Предупреждава само сигурно съвпадение; вероятното и възможното остават информативни. Изключено правило не се задейства никъде.',
  'Niet gecontroleerd: persoonsgegevens, bijzondere gegevens en geheimen. De privacycontrole staat uit bij Beveiliging.':
      'Не е проверено: лични данни, специални данни и тайни. Проверката на поверителността е изключена в Сигурност.',
  'Op deze slide': 'На този слайд',
  'Tijdens presenteren': 'По време на презентация',
  'Classificatie en privacy': 'Класификация и поверителност',
  'Logo tonen': 'Показване на лого',
  'Footer tonen': 'Показване на долен колонтитул',
  'Tabel bewerkbaar': 'Таблицата е редактируема',
  'Laat je de tabel tijdens het presenteren voor de zaal aanpassen. Staat standaard uit.':
      'Позволява ти да променяш таблицата пред публиката по време на презентация. По подразбиране е изключено.',
  'Automatisch doorgaan': 'Автоматично напред',
  'Persoonsgegevens': 'Лични данни',
  'Wijzigen': 'Промяна',
  'Automatisch afspelen': 'Автоматично възпроизвеждане',
  'Melden': 'Съобщаване',
  'Geaccepteerd': 'Прието',
  'Gewaarschuwd': 'С предупреждение',
  'Weggelaten': 'Пропуснато',
  'Bewerkbaar': 'Редактируемо',
  'De privacycontrole': 'Проверката за поверителност',
  'OciDeck leest je dia\'s na op gegevens die privacygevoelig kunnen zijn: identificatienummers, contactgegevens, telefoonnummers, bankrekeningen, sleutels en wachtwoorden, en bijzondere persoonsgegevens. Dat gebeurt volledig op dit apparaat: er wordt niets verstuurd, en de gevonden waarde zelf komt in geen enkele melding te staan.':
      'OciDeck преглежда слайдовете ти за данни, които може да са чувствителни: идентификационни номера, данни за контакт, телефонни номера, банкови сметки, ключове и пароли, както и специални категории лични данни. Всичко се случва на това устройство: нищо не се изпраща и намерената стойност не се появява в нито едно съобщение.',
  'De controle garandeert niet dat alles wordt gevonden; ze verkleint de kans dat er persoonsgegevens onbedoeld uitlekken.':
      'Проверката не гарантира, че всичко ще бъде открито; тя намалява риска лични данни да изтекат неволно.',
  'Tekst in afbeeldingen blijft buiten beeld, gelinkte bestanden worden niet geopend, en gegevens zonder herkenbaar patroon herkent geen enkele scanner. Een dia zonder meldingen is een dia waarin wíj niets hebben gevonden, niet een dia waarvan vaststaat dat er niets in staat. Wat je deelt, blijft jouw beslissing en jouw verantwoordelijkheid.':
      'Текстът в изображенията остава извън обхват, свързаните файлове не се отварят, а данни без разпознаваем модел не разпознава нито един скенер. Слайд без находки е слайд, в който *ние* не сме открили нищо — а не слайд, за който е доказано, че не съдържа нищо. Това, което споделяш, остава твое решение и твоя отговорност.',
  'telefoonnummer': 'телефонен номер',
  'Voor wie is deze export?': 'За кого е този експорт?',
  'Volledig': 'Пълен',
  'Geredigeerd': 'Заличен',
  'Voor de opdrachtgever of auditor: alleen wat je zelf op "weglaten" hebt gezet, gaat eruit. De rest blijft leesbaar, zodat een derde partij de bevindingen kan controleren.':
      'За възложителя или одитора: премахва се само това, което сте задали като „заличаване“. Останалото остава четимо, за да може трета страна да провери констатациите.',
  'Voor de bredere kring: alles wat de controle vindt gaat eruit, ook op slides die je hebt geaccepteerd. Het bestand krijgt "-geredigeerd" in de naam.':
      'За по-широк кръг: премахва се всичко, което проверката намери, включително на приети слайдове. Файлът получава „-geredigeerd“ в името.',
  'tabel met persoonsgegevens (rijen×kolommen)':
      'таблица с лични данни (редове×колони)',
  'massa-persoonsgegevens op één slide': 'масови лични данни на един слайд',
  'gebruikerspad met een naam erin': 'потребителски път с име в него',
  'toegangstoken in een link': 'токен за достъп в връзка',
  'persoonsgegeven in een link': 'лични данни във връзка',
  'deellink met ingebakken toegang': 'връзка за споделяне с вграден достъп',
  'e-mailadres in een link': 'имейл адрес във връзка',
  'ingesloten afbeelding — wij kunnen er niet in kijken':
      'вградено изображение — не можем да погледнем вътре',
  'Je eigen gegevens': 'Вашите собствени данни',
  'Eén per regel: je naam, e-mailadres, telefoonnummer of het domein van je organisatie. Wat hier staat wordt niet gemeld en niet geredigeerd — het is de afzender, geen bevinding. Een domein (example.org) dekt elk adres eronder.':
      'По едно на ред: вашето име, имейл, телефон или домейнът на организацията ви. Каквото е тук, не се съобщава и не се заличава — това е подателят, а не констатация. Домейн (example.org) покрива всеки адрес под него.',
  'Bij onafgehandelde persoonsgegevens': 'При необработени лични данни',
  'Export afgebroken vanwege privacybevindingen.':
      'Експортът е прекратен заради констатации за поверителност.',
  'Export blokkeren': 'Блокиране на експорта',
  'Export geblokkeerd': 'Експортът е блокиран',
  'Export geblokkeerd: er staan persoonsgegevens in dit deck waarvoor nog geen keuze is gemaakt.':
      'Експортът е блокиран: тази презентация съдържа лични данни, за които още не сте решили.',
  'Kies per slide wat er moet gebeuren, of exporteer bewust zoals het is.':
      'Изберете за всеки слайд какво да стане или съзнателно експортирайте както е.',
  'Maak per slide een keuze (accepteren, waarschuwen of weglaten) voordat je exporteert. Dit is zo ingesteld bij Beveiliging.':
      'Направете избор за всеки слайд (приемане, предупреждение или заличаване) преди експорт. Настроено е в Сигурност.',
  'Niets doen': 'Не прави нищо',
  'Persoonsgegevens in dit deck': 'Лични данни в тази презентация',
  'Verder in dit deck:': 'Другаде в тази презентация:',
